"""Measured local image -> detector/OCR -> VisualScene -> full VIR pipeline."""

from dataclasses import dataclass
from time import perf_counter

from virvision.scene import VisualScene, scene_to_dict
from virvision.vir.serializer import serialize_vir

from .base import ObjectDetector, OCRProvider, ProviderInfo
from .image import LoadedImage, load_image
from .normalize import fuse_scene, normalize_objects, normalize_texts
from .profiling import ResourceMetrics, ResourceMonitor


def _measure(callable_):
    started = perf_counter()
    value = callable_()
    return value, (perf_counter() - started) * 1000


@dataclass(frozen=True)
class PerceptionTimings:
    image_load_ms: float
    detector_cold_start_model_load_ms: float
    detector_warmup_ms: float
    object_detection_ms: float
    ocr_cold_start_model_load_ms: float
    ocr_warmup_ms: float
    ocr_ms: float
    scene_fusion_ms: float
    vir_serialize_ms: float
    total_pre_llm_ms: float
    warmup_runs: int

    def to_dict(self) -> dict:
        return vars(self).copy()


@dataclass(frozen=True)
class PerceptionResult:
    image: LoadedImage
    scene: VisualScene
    vir: str
    detector: ProviderInfo
    ocr: ProviderInfo
    timings: PerceptionTimings
    resources: ResourceMetrics
    config_snapshot: dict

    def to_dict(self) -> dict:
        return {
            "image": self.image.to_dict(),
            "providers": {"detector": self.detector.to_dict(), "ocr": self.ocr.to_dict()},
            "timings_ms": self.timings.to_dict(),
            "resources": self.resources.to_dict(),
            "config_snapshot": self.config_snapshot,
            "scene": scene_to_dict(self.scene),
            "vir": self.vir,
            "measurements": {
                "image_perception_executed": True,
                "llm_inference_executed": False,
                "accuracy": None,
                "quality_retention": None,
            },
        }


class PerceptionPipeline:
    def __init__(
        self,
        detector: ObjectDetector,
        ocr: OCRProvider,
        *,
        warmup_runs: int = 0,
        max_objects: int | None = None,
        ocr_dedup_iou: float = 0.80,
        config_snapshot: dict | None = None,
    ):
        if isinstance(warmup_runs, bool) or not isinstance(warmup_runs, int) or warmup_runs < 0:
            raise ValueError("warmup_runs must be a nonnegative integer")
        self.detector = detector
        self.ocr = ocr
        self.warmup_runs = warmup_runs
        self.max_objects = max_objects
        self.ocr_dedup_iou = ocr_dedup_iou
        self.config_snapshot = config_snapshot or {}

    def analyze(self, path) -> PerceptionResult:
        total_started = perf_counter()
        with ResourceMonitor() as resources:
            image = load_image(path)
            _, detector_load_ms = _measure(self.detector.load)
            _, detector_warmup_ms = _measure(
                lambda: [self.detector.detect(image) for _ in range(self.warmup_runs)]
            )
            raw_objects, detector_ms = _measure(lambda: self.detector.detect(image))
            _, ocr_load_ms = _measure(self.ocr.load)
            _, ocr_warmup_ms = _measure(
                lambda: [self.ocr.extract(image) for _ in range(self.warmup_runs)]
            )
            raw_texts, ocr_ms = _measure(lambda: self.ocr.extract(image))
            fusion_started = perf_counter()
            objects = normalize_objects(
                raw_objects, image.width, image.height, max_objects=self.max_objects
            )
            texts = normalize_texts(
                raw_texts, image.width, image.height, dedup_iou=self.ocr_dedup_iou
            )
            scene = fuse_scene(image.width, image.height, objects, texts)
            fusion_ms = (perf_counter() - fusion_started) * 1000
            vir, vir_ms = _measure(lambda: serialize_vir(scene))
            total_ms = (perf_counter() - total_started) * 1000
        timings = PerceptionTimings(
            image.load_ms,
            detector_load_ms,
            detector_warmup_ms,
            detector_ms,
            ocr_load_ms,
            ocr_warmup_ms,
            ocr_ms,
            fusion_ms,
            vir_ms,
            total_ms,
            self.warmup_runs,
        )
        return PerceptionResult(
            image,
            scene,
            vir,
            self.detector.info,
            self.ocr.info,
            timings,
            resources.metrics,
            self.config_snapshot,
        )


def create_pipeline(perception_config) -> PerceptionPipeline:
    from .providers import EasyOCRProvider, UltralyticsDetector

    detector_config = perception_config.detector
    ocr_config = perception_config.ocr
    detector = UltralyticsDetector(
        model=detector_config.model,
        confidence=detector_config.confidence,
        iou=detector_config.iou,
        device=detector_config.device,
        max_objects=detector_config.max_objects,
        image_size=detector_config.image_size,
    )
    ocr = EasyOCRProvider(
        languages=ocr_config.languages,
        device=ocr_config.device,
        model_storage_directory=ocr_config.model_storage_directory,
        download_enabled=ocr_config.download_enabled,
        detector_network=ocr_config.detector_network,
        min_confidence=ocr_config.confidence,
    )
    return PerceptionPipeline(
        detector,
        ocr,
        warmup_runs=perception_config.warmup_runs,
        max_objects=detector_config.max_objects,
        ocr_dedup_iou=ocr_config.dedup_iou,
        config_snapshot=perception_config.to_dict(),
    )
